  it('metadata is optional and defaults to undefined', () => {
    const entry: LogEntry = {
      id: 'log-3',
      timestamp: '2026-06-10T12:02:00Z',
      type: 'error',
      content: 'Something broke',
    };

    expect(entry.metadata).toBeUndefined();
