  it('metadata holds arbitrary key-value pairs', () => {
    const entry: LogEntry = {
      id: 'log-4',
      timestamp: '2026-06-10T12:03:00Z',
      type: 'decision',
      content: 'Approved',
      metadata: { score: 95, reviewedBy: 'Alice', notes: ['good', 'fast'] },
