import { afterEach, beforeEach } from 'bun:test';
import { mkdir, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

/**
 * Registers beforeEach/afterEach hooks to create and clean up a temp directory.
 * Call inside a describe() block to isolate temp dir to that block's tests.
 *
 * The directory is created in beforeEach and recursively removed in afterEach.
 */
export function useTempDir(): { getDir: () => string } {
  let dir: string;

  beforeEach(async () => {
    dir = join(tmpdir(), `test-${Date.now()}-${Math.random().toString(36).slice(2)}`);
    await mkdir(dir, { recursive: true });
  });

  afterEach(async () => {
    await rm(dir, { recursive: true, force: true });
  });

  return {
    getDir: () => dir,
  };
}

import { afterEach, beforeEach } from 'bun:test';

/**
 * Creates a process.env sandbox that saves state in beforeEach and restores it in afterEach.
 * Call inside a describe() block to isolate env changes to that block's tests.
 */
export function useEnvSandbox(): void {
  let savedEnv: Record<string, string | undefined>;
  beforeEach(() => {
    savedEnv = { ...process.env };
  });
  afterEach(() => {
    const currentKeys = new Set(Object.keys(process.env));
    const originalKeys = new Set(Object.keys(savedEnv));
    for (const key of currentKeys) {
      // eslint-disable-next-line @typescript-eslint/no-dynamic-delete
      if (!originalKeys.has(key)) delete process.env[key];
    }
    for (const [key, val] of Object.entries(savedEnv)) {
      if (val !== undefined) process.env[key] = val;
    }
  });
}

